-- Where every item of the issued plans stands now.
CREATE TEMP TABLE _plan_now AS
WITH RECURSIVE s AS (
  SELECT i.id, i.planId, i.parentId, i.kind, i.title, i.position, i.materialUrl,
         ROW_NUMBER() OVER (PARTITION BY i.planId, i.parentId, i.kind, i.title ORDER BY i.position, i.id) AS occ
  FROM PlanItem i
), w(id, planId, key) AS (
  SELECT id, planId, '/' || kind || ':' || title || '#' || occ FROM s WHERE parentId IS NULL
  UNION ALL
  SELECT s.id, s.planId, w.key || '/' || s.kind || ':' || s.title || '#' || s.occ FROM s JOIN w ON s.parentId = w.id
)
SELECT w.id, w.planId, p.track, w.key AS old_key
FROM w JOIN Plan p ON p.id = w.planId
WHERE p.track IN ('java', 'javascript', 'python', 'manual');

CREATE TEMP TABLE _plan_place AS
SELECT c.id, c.planId, c.track,
  COALESCE(m.new_key, (SELECT n.key FROM _plan_new n WHERE n.track = c.track AND n.key = c.old_key)) AS new_key
FROM _plan_now c LEFT JOIN _plan_map m ON m.track = c.track AND m.old_key = c.old_key;

CREATE TEMP TABLE _plan_guard (what TEXT NOT NULL, n INTEGER NOT NULL CHECK (n = 0));

-- Nothing is lost silently: an item with a tick or a note must have a place.
SELECT 'an item with a tick or a note has no place in the updated plan', count(*)
FROM _plan_place k JOIN PlanItem i ON i.id = k.id
WHERE k.new_key IS NULL AND (i.done <> 0 OR (i.note IS NOT NULL AND trim(i.note) <> ''));

SELECT 'two items of one plan got the same place', count(*)
FROM (SELECT planId, new_key FROM _plan_place WHERE new_key IS NOT NULL GROUP BY planId, new_key HAVING count(*) > 1);

-- id of every place in every plan: the old item that took it, or a new one.
CREATE TEMP TABLE _plan_id AS
SELECT planId, new_key, id FROM _plan_place WHERE new_key IS NOT NULL;

SELECT p.id, n.key,
  lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-'
        || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))
FROM Plan p JOIN _plan_new n ON n.track = p.track
WHERE p.track IN ('java', 'javascript', 'python', 'manual')
  AND NOT EXISTS (SELECT 1 FROM _plan_id d WHERE d.planId = p.id AND d.new_key = n.key);

CREATE TEMP TABLE _plan_target AS
SELECT d.id, d.planId, n.kind, n.title, n.position, n.material_url,
  (SELECT x.id FROM _plan_id x WHERE x.planId = d.planId AND x.new_key = n.parent_key) AS parent_id
FROM _plan_id d JOIN Plan p ON p.id = d.planId JOIN _plan_new n ON n.track = p.track AND n.key = d.new_key;

-- New places first (no parent yet), then every item gets its title, place and parent.
SELECT t.id, t.planId, NULL, t.kind, t.title, t.position, t.material_url, 0
FROM _plan_target t WHERE NOT EXISTS (SELECT 1 FROM PlanItem i WHERE i.id = t.id);

UPDATE PlanItem SET
  kind = (SELECT t.kind FROM _plan_target t WHERE t.id = PlanItem.id),
  title = (SELECT t.title FROM _plan_target t WHERE t.id = PlanItem.id),
  position = (SELECT t.position FROM _plan_target t WHERE t.id = PlanItem.id),
  materialUrl = (SELECT t.material_url FROM _plan_target t WHERE t.id = PlanItem.id),
  parentId = (SELECT t.parent_id FROM _plan_target t WHERE t.id = PlanItem.id)
WHERE id IN (SELECT id FROM _plan_target);

-- What nothing matched (and carries no tick or note) goes.
DELETE FROM PlanItem WHERE id IN (SELECT id FROM _plan_place WHERE new_key IS NULL);

-- Guard: every plan of these tracks is now exactly its template.
CREATE TEMP TABLE _plan_after AS
WITH RECURSIVE s AS (
  SELECT i.id, i.planId, i.parentId, i.kind, i.title, i.position, i.materialUrl,
         ROW_NUMBER() OVER (PARTITION BY i.planId, i.parentId, i.kind, i.title ORDER BY i.position, i.id) AS occ
  FROM PlanItem i
), w(id, planId, key) AS (
  SELECT id, planId, '/' || kind || ':' || title || '#' || occ FROM s WHERE parentId IS NULL
  UNION ALL
  SELECT s.id, s.planId, w.key || '/' || s.kind || ':' || s.title || '#' || s.occ FROM s JOIN w ON s.parentId = w.id
)
SELECT w.id, w.planId, p.track, w.key, i.position, i.materialUrl
FROM w JOIN Plan p ON p.id = w.planId JOIN PlanItem i ON i.id = w.id
WHERE p.track IN ('java', 'javascript', 'python', 'manual');

SELECT 'an item of the old structure is left', count(*)
FROM _plan_after a
WHERE NOT EXISTS (SELECT 1 FROM _plan_new n WHERE n.track = a.track AND n.key = a.key AND n.position = a.position
                  AND n.material_url IS a.materialUrl);

SELECT 'an item of the updated template is missing', count(*)
FROM Plan p JOIN _plan_new n ON n.track = p.track
WHERE p.track IN ('java', 'javascript', 'python', 'manual') AND NOT EXISTS (SELECT 1 FROM _plan_after a WHERE a.planId = p.id AND a.key = n.key);

SELECT 'an item is cut off from its plan', count(*)
FROM PlanItem i JOIN Plan p ON p.id = i.planId
WHERE p.track IN ('java', 'javascript', 'python', 'manual') AND NOT EXISTS (SELECT 1 FROM _plan_after a WHERE a.id = i.id);

DROP TABLE _plan_guard;
DROP TABLE _plan_after;
DROP TABLE _plan_target;
DROP TABLE _plan_id;
DROP TABLE _plan_place;
DROP TABLE _plan_now;
DROP TABLE _plan_map;
DROP TABLE _plan_new;

COMMIT;
